func main() {
	app := fiber.New()

	app.Post("/decideUnsubscribe", func(c *fiber.Ctx) error {
		emailContent := c.Body()

		// Extract the "From" email address
		fromLine := strings.SplitN(string(emailContent), "\n", 5)[2]
		fromEmail := strings.TrimSpace(strings.Split(fromLine, ":")[1])

		// Check for unsubscribe keywords
		unsubscribeKeywords := []string{"unsubscribe", "remove me", "deregister me", "stop sending me", "delete me"}
		unsubscribe := false
		for _, keyword := range unsubscribeKeywords {
			if strings.Contains(strings.ToLower(string(emailContent)), keyword) {
				unsubscribe = true
				break
			}
		}

		// Create response
		response := map[string]interface{}{
			"email":      fromEmail,
			"unsubscribe": unsubscribe,
		}

		return c.JSON(response)
	})

	app.Listen("0.0.0.0:5000")
}
